	if text == "*" {
		return min, max, nil
	}
	resolve := func(token string) (int, error) {
		if value, err := strconv.Atoi(token); err == nil {
			return value, nil
		}
		if names != nil {
			if value, ok := names[strings.ToLower(token)]; ok {
