package service

import (
	"errors"
	"path/filepath"
	"testing"
	"time"

	"github.com/luwa07832/cron-job-manager/internal/store"
)

type fakeClock struct{ t time.Time }

func (f *fakeClock) now() time.Time { return f.t }
func (f *fakeClock) advance(d time.Duration) {
	f.t = f.t.Add(d)
}

func newTestService(t *testing.T, executor Executor) (*Service, *fakeClock) {
	t.Helper()
	st, err := store.Open(filepath.Join(t.TempDir(), "service.db"))
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	t.Cleanup(func() { st.Close() })
	clock := &fakeClock{t: time.Date(2026, 3, 10, 12, 0, 0, 0, time.UTC)}
	svc := NewWithClock(st, clock.now, executor)
	return svc, clock
}

func failingExecutor() Executor {
	return ExecutorFunc(func(_, action string) error {
		if action == "succeed" {
			return nil
		}
		return errors.New("boom")
	})
}

func TestCreateTaskReturnsScheduleInfo(t *testing.T) {
	svc, clock := newTestService(t, NewBuiltinExecutor())
	task, err := svc.CreateTask(TaskInput{Name: "n", Schedule: "0 9 * * *", Action: "succeed"})
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	if task.Schedule != "0 9 * * *" {
		t.Fatalf("schedule = %q", task.Schedule)
	}
	wantCurrent := time.Date(2026, 3, 10, 9, 0, 0, 0, time.UTC)
	wantNext := time.Date(2026, 3, 11, 9, 0, 0, 0, time.UTC)
	if task.CurrentFireTime == nil || !task.CurrentFireTime.Equal(wantCurrent) {
		t.Fatalf("current = %v, want %v", task.CurrentFireTime, wantCurrent)
	}
	if task.NextFireTime == nil || !task.NextFireTime.Equal(wantNext) {
		t.Fatalf("next = %v, want %v", task.NextFireTime, wantNext)
	}
	_ = clock
}

func TestTriggerRecordsAllTimingFields(t *testing.T) {
	svc, clock := newTestService(t, failingExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "*/30 * * * *", Action: "fail:disk full"})

	record, err := svc.TriggerScheduled(task.ID, TriggerInput{})
	if err != nil {
		t.Fatalf("trigger: %v", err)
	}
	wantPlanned := time.Date(2026, 3, 10, 12, 0, 0, 0, time.UTC)
	if !record.PlannedFireTime.Equal(wantPlanned) {
		t.Fatalf("planned = %v, want %v", record.PlannedFireTime, wantPlanned)
	}
	if !record.ActualFireTime.Equal(clock.t) {
		t.Fatalf("actual = %v, want %v", record.ActualFireTime, clock.t)
	}
	wantNext := time.Date(2026, 3, 10, 12, 30, 0, 0, time.UTC)
	if record.NextFireTime == nil || !record.NextFireTime.Equal(wantNext) {
		t.Fatalf("next = %v, want %v", record.NextFireTime, wantNext)
	}
	if record.Status != StatusFailure {
		t.Fatalf("status = %q, want failure", record.Status)
	}
	if record.FailureReason != "disk full" {
		t.Fatalf("reason = %q", record.FailureReason)
	}
	if record.RecordType != RecordOriginal {
		t.Fatalf("record type = %q", record.RecordType)
	}
	if record.StartedAt.IsZero() || record.FinishedAt.Before(record.StartedAt) {
		t.Fatalf("execution times invalid: %v %v", record.StartedAt, record.FinishedAt)
	}
	if record.OriginalRunID != "" {
		t.Fatalf("original record should not reference a chain root, got %q", record.OriginalRunID)
	}
}

func TestSuccessHasNoFailureReason(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "* * * * *", Action: "succeed"})
	record, err := svc.TriggerScheduled(task.ID, TriggerInput{})
	if err != nil {
		t.Fatalf("trigger: %v", err)
	}
	if record.Status != StatusSuccess {
		t.Fatalf("status = %q", record.Status)
	}
	if record.FailureReason != "" {
		t.Fatalf("success carried failure reason %q", record.FailureReason)
	}
}

func TestRepeatedTriggerSameSlotKeepsIndependentRecords(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "0 12 * * *", Action: "succeed"})
	slot := time.Date(2026, 3, 10, 12, 0, 0, 0, time.UTC)

	first, err := svc.TriggerScheduled(task.ID, TriggerInput{PlannedFireTime: slot})
	if err != nil {
		t.Fatalf("trigger 1: %v", err)
	}
	second, err := svc.TriggerScheduled(task.ID, TriggerInput{PlannedFireTime: slot})
	if err != nil {
		t.Fatalf("trigger 2: %v", err)
	}
	if first.ID == second.ID {
		t.Fatal("repeated trigger merged into one record")
	}

	result, err := svc.QueryWindow(slot.Add(-time.Minute), slot.Add(time.Minute))
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	if len(result.Executed) != 2 {
		t.Fatalf("executed = %d, want 2", len(result.Executed))
	}
}

func TestRetryChainOrderingAndFields(t *testing.T) {
	svc, clock := newTestService(t, failingExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "0 12 * * *", Action: "fail:again"})
	slot := time.Date(2026, 3, 10, 12, 0, 0, 0, time.UTC)

	original, err := svc.TriggerScheduled(task.ID, TriggerInput{PlannedFireTime: slot})
	if err != nil {
		t.Fatalf("trigger: %v", err)
	}
	clock.advance(2 * time.Minute)
	retry, err := svc.Retry(original.ID, time.Time{})
	if err != nil {
		t.Fatalf("retry: %v", err)
	}
	if retry.RecordType != RecordRetry {
		t.Fatalf("type = %q, want retry", retry.RecordType)
	}
	if retry.Attempt != 2 {
		t.Fatalf("attempt = %d, want 2", retry.Attempt)
	}
	if retry.OriginalRunID != original.ID || retry.ParentRunID != original.ID {
		t.Fatalf("chain links wrong: original=%s parent=%s root=%s",
			retry.OriginalRunID, retry.ParentRunID, original.ID)
	}
	if !retry.PlannedFireTime.Equal(clock.t) {
		t.Fatalf("retry planned = %v, want %v", retry.PlannedFireTime, clock.t)
	}
	if retry.FailureReason != "again" {
		t.Fatalf("retry reason = %q", retry.FailureReason)
	}

	clock.advance(time.Minute)
	retry2, err := svc.Retry(retry.ID, time.Time{})
	if err != nil {
		t.Fatalf("retry 2: %v", err)
	}
	if retry2.Attempt != 3 || retry2.OriginalRunID != original.ID || retry2.ParentRunID != retry.ID {
		t.Fatalf("retry 2 chain wrong: %+v", retry2)
	}

	window, err := svc.QueryWindow(slot.Add(-time.Hour), clock.t.Add(time.Hour))
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	if len(window.Executed) != 3 {
		t.Fatalf("executed = %d, want 3", len(window.Executed))
	}
	ids := map[string]string{}
	for _, run := range window.Executed {
		ids[run.ID] = run.RecordType
	}
	if ids[original.ID] != RecordOriginal || ids[retry.ID] != RecordRetry || ids[retry2.ID] != RecordRetry {
		t.Fatalf("retry records lost or mistyped: %v", ids)
	}
}

func TestRetryRejectsSuccess(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "* * * * *", Action: "succeed"})
	record, _ := svc.TriggerScheduled(task.ID, TriggerInput{})
	if _, err := svc.Retry(record.ID, time.Time{}); !errors.Is(err, ErrRunNotRetriable) {
		t.Fatalf("err = %v, want ErrRunNotRetriable", err)
	}
}

func TestUnknownTaskAndRunErrors(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	if _, err := svc.GetTask("missing"); !errors.Is(err, ErrTaskNotFound) {
		t.Fatalf("get: %v", err)
	}
	if err := svc.DeleteTask("missing"); !errors.Is(err, ErrTaskNotFound) {
		t.Fatalf("delete: %v", err)
	}
	if _, err := svc.UpdateTask("missing", TaskInput{Name: "n", Schedule: "* * * * *", Action: "succeed"}); !errors.Is(err, ErrTaskNotFound) {
		t.Fatalf("update: %v", err)
	}
	if _, err := svc.TriggerScheduled("missing", TriggerInput{}); !errors.Is(err, ErrTaskNotFound) {
		t.Fatalf("trigger: %v", err)
	}
	if _, err := svc.RunManual("missing"); !errors.Is(err, ErrTaskNotFound) {
		t.Fatalf("run: %v", err)
	}
	if _, err := svc.Retry("missing", time.Time{}); !errors.Is(err, ErrRunNotFound) {
		t.Fatalf("retry: %v", err)
	}
}

func TestInvalidScheduleRejected(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	if _, err := svc.CreateTask(TaskInput{Name: "n", Schedule: "not cron", Action: "succeed"}); !errors.Is(err, ErrInvalidSchedule) {
		t.Fatalf("err = %v", err)
	}
	if _, err := svc.ValidateSchedule("99 * * * *"); !errors.Is(err, ErrInvalidSchedule) {
		t.Fatalf("validate err = %v", err)
	}
}

func TestWindowPendingAndExecuted(t *testing.T) {
	svc, _ := newTestService(t, NewBuiltinExecutor())
	task, _ := svc.CreateTask(TaskInput{Name: "n", Schedule: "0 * * * *", Action: "succeed"})

	start := time.Date(2026, 3, 10, 13, 0, 0, 0, time.UTC)
	end := time.Date(2026, 3, 10, 16, 0, 0, 0, time.UTC)

	// Execute the 14:00 slot explicitly.
	executedAt := time.Date(2026, 3, 10, 14, 0, 0, 0, time.UTC)
	if _, err := svc.TriggerScheduled(task.ID, TriggerInput{PlannedFireTime: executedAt}); err != nil {
		t.Fatalf("trigger: %v", err)
	}

	result, err := svc.QueryWindow(start, end)
	if err != nil {
		t.Fatalf("query: %v", err)
	}
	if len(result.Executed) != 1 || !result.Executed[0].PlannedFireTime.Equal(executedAt) {
		t.Fatalf("executed = %+v", result.Executed)
	}
	gotPending := map[string]bool{}
	for _, pending := range result.Pending {
		gotPending[pending.PlannedFireTime.Format("15:04")] = true
		if pending.RecordType != RecordPending || pending.Status != "pending" {
			t.Fatalf("pending record shape wrong: %+v", pending)
		}
	}
